package com.elementalweakness;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Units;

@ConfigGroup(ElementalWeaknessConfig.GROUP)
public interface ElementalWeaknessConfig extends Config
{
	String GROUP = "elementalweakness";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show rune overlay",
		description = "Draw the weakness rune and percentage above checked NPCs",
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showChatMessage",
		name = "Show chat message",
		description = "Print '<NPC> - <X%> <Weakness>' in the chatbox",
		position = 2
	)
	default boolean showChatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayDuration",
		name = "Overlay duration",
		description = "How long the overlay stays on an NPC after checking (0 = while the NPC is visible)",
		position = 3
	)
	@Units(Units.SECONDS)
	default int overlayDuration()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "applyToSameName",
		name = "Overlay all NPCs with same name",
		description = "Also show the overlay on every other NPC that shares the checked NPC's name",
		position = 4
	)
	default boolean applyToSameName()
	{
		return true;
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Text colour",
		description = "Colour of the weakness percentage text",
		position = 5
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "autoCheck",
		name = "Auto-check when attacking with magic",
		description = "Automatically look up an NPC when you start attacking it while autocasting a spell (or using a powered staff)",
		position = 6
	)
	default boolean autoCheck()
	{
		return false;
	}

	@ConfigItem(
		keyName = "tintBySpell",
		name = "Colour overlay by autocast spell",
		description = "Green when your autocast spell matches the NPC's weakness, red when it doesn't. Non-elemental spells are not tinted",
		position = 7
	)
	default boolean tintBySpell()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hoverOnly",
		name = "Only show overlay on hover",
		description = "Only draw the rune overlay on the NPC under the mouse cursor",
		position = 8
	)
	default boolean hoverOnly()
	{
		return false;
	}


}

package com.elementalweakness;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Point;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class ElementalWeaknessOverlay extends Overlay
{
	private final Client client;
	private final ElementalWeaknessPlugin plugin;
	private final ElementalWeaknessConfig config;
	private final ItemManager itemManager;

	@Inject
	ElementalWeaknessOverlay(Client client, ElementalWeaknessPlugin plugin, ElementalWeaknessConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		Set<Integer> hovered = config.hoverOnly() ? hoveredNpcIndices() : null;
		String autocastElement = config.tintBySpell() ? plugin.getAutocastElement() : null;

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (hovered != null && !hovered.contains(npc.getIndex()))
			{
				continue;
			}
			Weakness weakness = plugin.getDisplayedWeakness(npc);
			if (weakness == null || !weakness.hasWeakness())
			{
				continue;
			}

			Color color = config.textColor();
			if (autocastElement != null)
			{
				color = autocastElement.equalsIgnoreCase(weakness.getElement()) ? Color.GREEN : Color.RED;
			}

			String text = weakness.getPercent() + "% " + weakness.getElement();
			int textWidth = graphics.getFontMetrics().stringWidth(text);
			final Point textLoc = npc.getCanvasTextLocation(graphics, text, npc.getLogicalHeight() + 40);
			if (textLoc == null)
			{
				continue;
			}

			BufferedImage rune = itemManager.getImage(weakness.getRuneItemId());
			if (rune != null)
			{
				int x = textLoc.getX() + textWidth / 2 - rune.getWidth() / 2;
				int y = textLoc.getY() - rune.getHeight() - graphics.getFontMetrics().getHeight();
				OverlayUtil.renderImageLocation(graphics, new Point(x, y), rune);
			}
			OverlayUtil.renderTextLocation(graphics, textLoc, text, color);
		}
		return null;
	}

	/** Indices of NPCs currently under the mouse, taken from the pending menu entries. */
	private Set<Integer> hoveredNpcIndices()
	{
		Set<Integer> result = new HashSet<>();
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			NPC npc = entry.getNpc();
			if (npc != null)
			{
				result.add(npc.getIndex());
			}
		}
		return result;
	}
}

package com.elementalweakness;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Elemental Weakness Checker",
	description = "Right-click an NPC to look up its elemental weakness on the OSRS wiki",
	tags = {"npc", "weakness", "elemental", "magic", "wiki"}
)
public class ElementalWeaknessPlugin extends Plugin
{
	private static final String CHECK_WEAKNESS = "Check weakness";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ElementalWeaknessConfig config;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ElementalWeaknessOverlay overlay;
	@Inject
	private ChatMessageManager chatMessageManager;
	@Inject
	private WikiClient wikiClient;

	/** Minimum gap between automatic re-announcements of the same NPC name. */
	private static final Duration AUTO_ANNOUNCE_INTERVAL = Duration.ofSeconds(30);

	private ExecutorService executor;

	/** Cached lookups by NPC name (lower-case). */
	/** Names currently being looked up. */
	private final Map<String, Weakness> cache = new ConcurrentHashMap<>();
	private final Map<String, Boolean> pending = new ConcurrentHashMap<>();
	/** NPC index -> time the overlay was requested. */
	private final Map<Integer, Instant> checkedNpcs = new ConcurrentHashMap<>();
	/** NPC name -> time the overlay was requested (for "apply to same name"). */
	private final Map<String, Instant> checkedNames = new ConcurrentHashMap<>();
	private final Map<String, Instant> autoAnnounced = new ConcurrentHashMap<>();

	@Provides
	ElementalWeaknessConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ElementalWeaknessConfig.class);
	}

	@Override
	protected void startUp()
	{
		executor = Executors.newSingleThreadExecutor();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		executor.shutdownNow();
		executor = null;
		cache.clear();
		pending.clear();
		checkedNpcs.clear();
		checkedNames.clear();
		autoAnnounced.clear();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuAction type = event.getMenuEntry().getType();
		if (!isNpcAction(type))
		{
			return;
		}

		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null || npc.getName() == null || !isAttackable(npc))
		{
			return;
		}

		// Only add one entry per NPC, even though several NPC options are added for it.
		// The identifier of an NPC menu entry is the NPC index.
		for (MenuEntry existing : client.getMenu().getMenuEntries())
		{
			if (existing.getType() == MenuAction.RUNELITE
				&& CHECK_WEAKNESS.equals(existing.getOption())
				&& existing.getIdentifier() == event.getIdentifier())
			{
				return;
			}
		}

		client.getMenu().createMenuEntry(-1)
			.setOption(CHECK_WEAKNESS)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier())
			.setParam0(event.getActionParam0())
			.setParam1(event.getActionParam1())
			.onClick(e -> checkNpc(npc, false));
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		checkedNpcs.remove(event.getNpc().getIndex());
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (!config.autoCheck() || event.getSource() != client.getLocalPlayer())
		{
			return;
		}
		Actor target = event.getTarget();
		if (!(target instanceof NPC) || !isUsingMagic())
		{
			return;
		}
		NPC npc = (NPC) target;
		if (npc.getName() != null && isAttackable(npc))
		{
			checkNpc(npc, true);
		}
	}


	/** True when the player is autocasting a spell (this includes powered staves). */
	private boolean isUsingMagic()
	{
		return client.getVarbitValue(VarbitID.AUTOCAST_SPELL) != 0;
	}

	/**
	 * Element of the currently autocast spell, or null if none / not an elemental spell.
	 * Autocast ids: strikes 1-4, bolts 5-8, blasts 9-12, waves 13-16, surges 48-51,
	 * each in the order air, water, earth, fire.
	 */
	String getAutocastElement()
	{
		return autocastElement(client.getVarbitValue(VarbitID.AUTOCAST_SPELL));
	}

	static String autocastElement(int id)
	{
		int idx;
		if (id >= 1 && id <= 16)
		{
			idx = (id - 1) % 4;
		}
		else if (id >= 48 && id <= 51)
		{
			idx = id - 48;
		}
		else
		{
			return null;
		}
		switch (idx)
		{
			case 0:
				return "Air";
			case 1:
				return "Water";
			case 2:
				return "Earth";
			default:
				return "Fire";
		}
	}

	/** True if the NPC has an "Attack" option in its (transformed) definition. */
	private static boolean isAttackable(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null || comp.getActions() == null)
		{
			return false;
		}
		for (String action : comp.getActions())
		{
			if ("Attack".equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isNpcAction(MenuAction type)
	{
		switch (type)
		{
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case EXAMINE_NPC:
			case WIDGET_TARGET_ON_NPC:
				return true;
			default:
				return false;
		}
	}

	private void checkNpc(NPC npc, boolean automatic)
	{
		String name = npcDisplayName(npc);
		if (name == null)
		{
			return;
		}
		String key = name.toLowerCase();
		Instant now = Instant.now();
		checkedNpcs.put(npc.getIndex(), now);
		checkedNames.put(key, now);

		Weakness cached = cache.get(key);
		if (cached != null)
		{
			if (!automatic || shouldAutoAnnounce(key, now))
			{
				announce(name, cached);
			}
			return;
		}
		if (pending.putIfAbsent(key, Boolean.TRUE) != null)
		{
			return; // already fetching
		}

		executor.submit(() ->
		{
			try
			{
				Weakness w = wikiClient.lookup(name);
				cache.put(key, w);
				clientThread.invokeLater(() ->
				{
					if (!automatic || shouldAutoAnnounce(key, Instant.now()))
					{
						announce(name, w);
					}
				});
			}
			catch (Exception ex)
			{
				log.warn("Failed to look up weakness for {}", name, ex);
				if (!automatic)
				{
					clientThread.invokeLater(() -> sendChat(name + " - could not fetch weakness from the wiki", ChatColorType.HIGHLIGHT));
				}
			}
			finally
			{
				pending.remove(key);
			}
		});
	}

	private boolean shouldAutoAnnounce(String key, Instant now)
	{
		Instant last = autoAnnounced.get(key);
		if (last != null && Duration.between(last, now).compareTo(AUTO_ANNOUNCE_INTERVAL) < 0)
		{
			return false;
		}
		autoAnnounced.put(key, now);
		return true;
	}

	private void announce(String name, Weakness w)
	{
		if (!config.showChatMessage())
		{
			return;
		}
		if (w.hasWeakness())
		{
			sendChat(name + " - " + w.getPercent() + "% " + w.getElement(), ChatColorType.HIGHLIGHT);
		}
		else
		{
			sendChat(name + " - No elemental weakness", ChatColorType.NORMAL);
		}
	}

	private void sendChat(String message, ChatColorType color)
	{
		String msg = new ChatMessageBuilder().append(color).append(message).build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(msg)
			.build());
	}

	/** Name with colour tags / level suffix stripped, using the transformed composition where applicable. */
	private static String npcDisplayName(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		String name = comp != null ? comp.getName() : npc.getName();
		if (name == null)
		{
			return null;
		}
		name = Text.removeTags(name).replace(' ', ' ').trim();
		return name.isEmpty() ? null : name;
	}

	/**
	 * Weakness to draw for this NPC, or null if it should not be shown.
	 */
	Weakness getDisplayedWeakness(NPC npc)
	{
		Instant checked = checkedNpcs.get(npc.getIndex());
		String name = npcDisplayName(npc);
		if (checked == null && config.applyToSameName() && name != null)
		{
			checked = checkedNames.get(name.toLowerCase());
		}
		if (checked == null || name == null)
		{
			return null;
		}

		int duration = config.overlayDuration();
		if (duration > 0 && Duration.between(checked, Instant.now()).getSeconds() > duration)
		{
			return null;
		}
		return cache.get(name.toLowerCase());
	}
}

package com.elementalweakness;

import lombok.Value;
import net.runelite.api.gameval.ItemID;

/**
 * Result of a wiki lookup. {@code element} is null when the NPC has no elemental weakness.
 */
@Value
public class Weakness
{
	public static final Weakness NONE = new Weakness(null, 0);

	String element;
	int percent;

	public boolean hasWeakness()
	{
		return element != null;
	}

	/** Item id of the elemental rune matching this weakness, or -1. */
	public int getRuneItemId()
	{
		if (element == null)
		{
			return -1;
		}
		switch (element.toLowerCase())
		{
			case "air":
				return ItemID.AIRRUNE;
			case "water":
				return ItemID.WATERRUNE;
			case "earth":
				return ItemID.EARTHRUNE;
			case "fire":
				return ItemID.FIRERUNE;
			default:
				return -1;
		}
	}
}

package com.elementalweakness;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches NPC infobox wikitext from the OSRS wiki MediaWiki API and extracts
 * the {@code elementalweaknesstype} / {@code elementalweaknesspercent} parameters.
 */
@Slf4j
@Singleton
public class WikiClient
{
	private static final String API = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "RuneLite Elemental Weakness plugin";

	// Matches e.g. "|elementalweaknesstype = Fire" or "|elementalweaknesstype1 = Fire"
	private static final Pattern TYPE = Pattern.compile("\\|\\s*elementalweaknesstype(\\d*)\\s*=\\s*([A-Za-z]+)");
	private static final Pattern PERCENT = Pattern.compile("\\|\\s*elementalweaknesspercent(\\d*)\\s*=\\s*(\\d+)");

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	public WikiClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	public Weakness lookup(String npcName) throws IOException
	{
		String wikitext = fetchWikitext(npcName);
		if (wikitext == null)
		{
			throw new IOException("No wiki page found for '" + npcName + "'");
		}
		return parse(wikitext);
	}

	private String fetchWikitext(String page) throws IOException
	{
		HttpUrl url = HttpUrl.parse(API).newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", page)
			.addQueryParameter("prop", "wikitext")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = okHttpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new IOException("Wiki request failed: HTTP " + response.code());
			}
			JsonObject json = gson.fromJson(response.body().string(), JsonObject.class);
			if (json.has("error"))
			{
				log.debug("Wiki error for {}: {}", page, json.get("error"));
				return null;
			}
			JsonObject parse = json.getAsJsonObject("parse");
			if (parse == null || !parse.has("wikitext"))
			{
				return null;
			}
			return parse.getAsJsonObject("wikitext").get("*").getAsString();
		}
	}

	static Weakness parse(String wikitext)
	{
		Matcher t = TYPE.matcher(wikitext);
		if (!t.find())
		{
			return Weakness.NONE;
		}
		String element = t.group(2);
		String suffix = t.group(1);
		if (element.equalsIgnoreCase("none"))
		{
			return Weakness.NONE;
		}

		// Prefer the percent with the same version suffix as the type we matched
		int percent = 0;
		Matcher p = PERCENT.matcher(wikitext);
		while (p.find())
		{
			percent = Integer.parseInt(p.group(2));
			if (p.group(1).equals(suffix))
			{
				break;
			}
		}
		return new Weakness(capitalize(element), percent);
	}

	private static String capitalize(String s)
	{
		return s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
	}
}

package com.elementalweakness;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class AutocastElementTest
{
	@Test
	public void elementalSpellLines()
	{
		assertEquals("Air", ElementalWeaknessPlugin.autocastElement(1));   // Wind Strike
		assertEquals("Fire", ElementalWeaknessPlugin.autocastElement(4));  // Fire Strike
		assertEquals("Water", ElementalWeaknessPlugin.autocastElement(6)); // Water Bolt
		assertEquals("Earth", ElementalWeaknessPlugin.autocastElement(15)); // Earth Wave
		assertEquals("Air", ElementalWeaknessPlugin.autocastElement(48));  // Wind Surge
		assertEquals("Fire", ElementalWeaknessPlugin.autocastElement(51)); // Fire Surge
	}

	@Test
	public void nonElementalSpells()
	{
		assertNull(ElementalWeaknessPlugin.autocastElement(0));
		assertNull(ElementalWeaknessPlugin.autocastElement(18)); // Magic Dart
		assertNull(ElementalWeaknessPlugin.autocastElement(46)); // Ice Barrage
	}
}

package com.elementalweakness;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ElementalWeaknessPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ElementalWeaknessPlugin.class);
		RuneLite.main(args);
	}
}

package com.elementalweakness;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import org.junit.Test;

public class WikiClientTest
{
	@Test
	public void parsesSingleInfobox()
	{
		Weakness w = WikiClient.parse("{{Infobox Monster\n|name = Blue dragon\n|elementalweaknesstype = Fire\n|elementalweaknesspercent = 50\n}}");
		assertEquals("Fire", w.getElement());
		assertEquals(50, w.getPercent());
	}

	@Test
	public void parsesVersionedInfobox()
	{
		Weakness w = WikiClient.parse("|elementalweaknesstype1 = Water\n|elementalweaknesspercent1 = 30\n|elementalweaknesstype2 = Water\n|elementalweaknesspercent2 = 30\n");
		assertEquals("Water", w.getElement());
		assertEquals(30, w.getPercent());
	}

	@Test
	public void noWeakness()
	{
		assertFalse(WikiClient.parse("{{Infobox Monster\n|name = Goblin\n}}").hasWeakness());
		assertFalse(WikiClient.parse("|elementalweaknesstype = None\n").hasWeakness());
	}
}
